        sch.Process();
    } else if constexpr (dType == TPL_FP32) {
        ElementwiseSch<schMode, AtanOp::AtanDag<float>::OpDag> sch(&tilingData, &pipe);
        sch.Init(x, y);
        sch.Process();
    }
    return;
}

