#include "arch35/axpy_struct.h"
#include "atvoss/broadcast/broadcast_sch.h"

using namespace AscendC;
using namespace Ops::Base;

template <uint64_t Mode, typename T>
__global__ __aicore__ void axpy_op(GM_ADDR x1, GM_ADDR x2, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    if constexpr (std::is_same<T, int32_t>::value) {
        using OpDag = typename AxpyOp::AxpyCompute<T, AxpyOp::CAST_RINT_MODE, AxpyOp::CAST_TRUNC_MODE>::OpDag;
        BroadcastSch<Mode, OpDag> sch(tiling);
        sch.Process(x1, x2, y);
    } else if constexpr (std::is_same<T, float>::value) {
        using OpDag = typename AxpyOp::AxpyComputeFloat::OpDag;
        BroadcastSch<Mode, OpDag> sch(tiling);
        sch.Process(x1, x2, y);
    } else {
        using OpDag = typename AxpyOp::AxpyCompute<T, AxpyOp::CAST_NONE_MODE, AxpyOp::CAST_RINT_MODE>::OpDag;
        BroadcastSch<Mode, OpDag> sch(tiling);
        sch.Process(x1, x2, y);
    }
}

template <uint64_t schMode>
__global__ __aicore__ void axpy(GM_ADDR x1, GM_ADDR x2, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    axpy_op<schMode, DTYPE_X1>(x1, x2, y, workspace, tiling);
}

