    using PromoteType = __reduceType::GetPromoteType<DTYPE_X>::T;
    using Op = ReduceSch<REDUCE_TPL_VALUE, BiasAddGrad::BiasAddGradDag<DTYPE_X, PromoteType>::OpDag>;
    Op op(&tilingData);
    op.Init(&pipe, x, y, userWS);
    op.Process();
}

