template <bool templateType, bool isEmptyTensor>
__global__ __aicore__ void data_compare(GM_ADDR x1, GM_ADDR x2, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    REGISTER_TILING_DEFAULT(DataCompareTilingData);
