        NsDataCompare::DataCompareKernel<DTYPE_X1> op;
        op.InitGroup(x1, x2, y, workspace, &tilingData);
        op.ProcessGroup();
    } else {
        // Normal 模板
        NsDataCompare::DataCompareKernel<DTYPE_X1> op;
        op.Init(x1, x2, y, &tilingData);
        op.Process();
    }
}

