    } else if constexpr (dType == TPL_FP16) {
        ElementwiseSch<schMode, Expm1Op::Expm1DAG<half>::OpDag> sch(&tilingData, &pipe);
        sch.Init(x, y);
        sch.Process();
    }
}

} // namespace AscendC

