#define TWO_DIMS_BFLOAT16_GRP64 1010012
#define TWO_DIMS_HALF_USEUB_GRP64 1010110
#define TWO_DIMS_FLOAT_USEUB_GRP64 1010111
#define TWO_DIMS_BFLOAT16_USEUB_GRP64 1010112

