        InvokeTemplateGroupedUnequalCPerf<half, int64_t, USE_UB>(grad_y, group_idx, grad_bias, userWS, tilingData);
    } else if (TILING_KEY_IS(TWO_DIMS_BFLOAT16_USEUB_GRP64_PERF)) {
