            ElementwiseSch<0UL, InvertDag<int16_t>::OpDag> sch(&tilingData, &pipe);
            sch.Init(x, y);
            sch.Process();
        } else if constexpr (std::is_same<DTYPE_X, int32_t>::value) {
            ElementwiseSch<0UL, InvertDag<int32_t>::OpDag> sch(&tilingData, &pipe);
            sch.Init(x, y);
