#include "arch35/lerp_f16_nddma_without_loops.h"
#include "arch35/lerp_f16_nddma_with_loops.h"
#include "arch35/lerp_f32_nddma_without_loops.h"
#include "arch35/lerp_f32_nddma_with_loops.h"
