        op.InitBuffer();
        op.GetLocalTensor();
        op.Process();
        op.ReleaseEventID();
#if !(defined(__NPU_ARCH__) && (__NPU_ARCH__ == 3003 || __NPU_ARCH__ == 3113))
    } else if (TILING_KEY_IS(2)) {
        TPipe pipe;
        KernelMulAddnAlignF16<bfloat16_t, float> op;
        op.Init(x1, x2, y, workspace, &tilingData, &pipe);
        op.InitBuffer();
        op.GetLocalTensor();
        op.Process();
        op.ReleaseEventID();
#endif
    }
}

