        using Op = ReduceSch<REDUCE_TPL_VALUE, ReduceLogSumExp::ReduceLogSumExpDag<DTYPE_X>::OpDag>;
        Op op(&tilingData);
        op.Init(&pipe, x, y, userWS);
        op.Process(GetDumpValue<DTYPE_X>());
    }
}

