extern "C" __global__ __aicore__ void assign(GM_ADDR ref, GM_ADDR value, GM_ADDR out, GM_ADDR workspace, GM_ADDR tiling)
{
    if (workspace == nullptr) {
        return;
    }

    SetSysWorkspace(workspace);
    GM_ADDR userWS = GetUserWorkspace(workspace);
    if (userWS == nullptr) {
        return;
    }
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_AIV_ONLY);
    GET_TILING_DATA(tilingData, tiling);
    // tilingkey对应位宽 1/2/4/8
    if (TILING_KEY_IS(TILING_KEY_ONE_BYTE)) {
        TensorMove::TensorMoveKernel<int8_t> op;
        op.Init(value, ref, userWS, tilingData);
        op.Process();
    } else if (TILING_KEY_IS(TILING_KEY_TWO_BYTE)) {
        TensorMove::TensorMoveKernel<int16_t> op;
        op.Init(value, ref, userWS, tilingData);
        op.Process();
    } else if (TILING_KEY_IS(TILING_KEY_FOUR_BYTE)) {
        TensorMove::TensorMoveKernel<int32_t> op;
        op.Init(value, ref, userWS, tilingData);
        op.Process();
    } else if (TILING_KEY_IS(TILING_KEY_EIGHT_BYTE)) {
        TensorMove::TensorMoveKernel<int64_t> op;
        op.Init(value, ref, userWS, tilingData);
        op.Process();
    } else if (TILING_KEY_IS(TILING_KEY_ONE_BYTE_SCALAR)) {
        AssignScalar::AssignScalarKernel<int8_t> op;
        op.Init(value, ref, userWS, tilingData);
        op.Process();
    } else if (TILING_KEY_IS(TILING_KEY_TWO_BYTE_SCALAR)) {
        AssignScalar::AssignScalarKernel<int16_t> op;
        op.Init(value, ref, userWS, tilingData);
        op.Process();
    } else if (TILING_KEY_IS(TILING_KEY_FOUR_BYTE_SCALAR)) {
        AssignScalar::AssignScalarKernel<int32_t> op;
        op.Init(value, ref, userWS, tilingData);
        op.Process();
    } else if (TILING_KEY_IS(TILING_KEY_EIGHT_BYTE_SCALAR)) {
        AssignScalar::AssignScalarKernel<int64_t> op;
        op.Init(value, ref, userWS, tilingData);
        op.Process();
    }
