        op.Init2D(x, paddings, y, usrWorkspace, tiling_data);
        op.ProcessBigShape();
    } else if (TILING_KEY_IS(221)) {
        CircularPadGrad2D<half, float, true> op(&pipe);
        op.Init2D(x, paddings, y, usrWorkspace, tiling_data);
        op.ProcessSmallShape();
    } else if (TILING_KEY_IS(222)) {
        CircularPadGrad2D<half, float, true> op(&pipe);
        op.Init2D(x, paddings, y, usrWorkspace, tiling_data);
        op.ProcessBigShape();
