#define NO_CLEAR_SPLIT_FRONT_AXIS_NDDMA_INT16 242
#define NO_CLEAR_SPLIT_FRONT_AXIS_NDDMA_INT32 244
#define NO_CLEAR_SPLIT_FRONT_AXIS_NDDMA_INT64 248

